import {describe, it} from 'node:test';
import {assert} from 'chai';
import sinon from 'sinon';

import {Buffer} from './Buffer.js';

describe('Buffer', () => {
  it('should keep values', () => {
    const buffer = new Buffer<number>(2);
    assert.deepEqual(buffer.get(), []);
    buffer.add(1);
    assert.deepEqual(buffer.get(), [1]);
    buffer.add(2);
    assert.deepEqual(buffer.get(), [1, 2]);
    buffer.add(3);
    assert.deepEqual(buffer.get(), [2, 3]);
  });

  it('should call `onItemRemoved`', () => {
    const onRemoved = sinon.mock();
    const buffer = new Buffer<number>(2, onRemoved);
    buffer.add(1);
    sinon.assert.notCalled(onRemoved);
    buffer.add(2);
    sinon.assert.notCalled(onRemoved);
    buffer.add(3);
    sinon.assert.calledOnceWithExactly(onRemoved, 1);
  });
});
